请对以下 case 进行三维加权评分。

=== case_id ===
Case-20-notif-aggregate-008

=== 用户原始指令 (query.txt) ===
点一下能进钉钉看消息，紧急的要标红色那种

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "点一下能进钉钉看消息，紧急的要标红色那种",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.alibaba.dingtalk",
        "abilityName": "",
        "uri": "dingtalk://dingtalkclient/page/message"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "notifications": {
        "appName": {
          "type": "string",
          "description": "通知来源应用名称，用于标识消息入口。",
          "sampleValue": "钉钉消息"
        },
        "appSubtitle": {
          "type": "string",
          "description": "通知聚合的短说明。",
          "sampleValue": "聚合通知"
        },
        "unreadSummary": {
          "type": "string",
          "description": "当前未读通知数量摘要。",
          "sampleValue": "7条未读"
        },
        "latestTitle": {
          "type": "string",
          "description": "最新或最需要关注的消息摘要。",
          "sampleValue": "项目群审批待看"
        },
        "urgentLabel": {
          "type": "string",
          "description": "紧急消息状态标签。",
          "sampleValue": "紧急"
        },
        "urgentCountText": {
          "type": "string",
          "description": "紧急消息数量展示文本。",
          "sampleValue": "2条"
        },
        "statusHint": {
          "type": "string",
          "description": "紧急消息处理提示。",
          "sampleValue": "需尽快看"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bell_fill.svg",
      "description": "通知提醒铃铛实心图标，适合用于消息通知聚合和提醒状态识别；黑色 SVG，需放在浅色图标底板上保证可读。"
    }
  ]
}

